import ast,json,os,pathlib,subprocess,time
base=pathlib.Path('/opt/price-collector')
def command(args,timeout=12):
 p=subprocess.run(args,capture_output=True,text=True,timeout=timeout)
 if p.returncode:raise RuntimeError('read-only command failed '+args[0]+' code '+str(p.returncode))
 return p.stdout.strip()
sql="""BEGIN READ ONLY; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
WITH relations AS MATERIALIZED (
 SELECT n.nspname AS schema_name,c.relname,c.relkind,
 pg_total_relation_size(c.oid) AS total_bytes,pg_table_size(c.oid) AS table_toast_bytes,pg_indexes_size(c.oid) AS index_bytes
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN ('public','raw_capture') AND c.relkind IN ('r','m','p'))
SELECT json_build_object('transaction_read_only',current_setting('transaction_read_only'),
 'statement_timeout',current_setting('statement_timeout'),'lock_timeout',current_setting('lock_timeout'),
 'database',current_database(),'database_bytes',pg_database_size(current_database()),
 'data_directory',current_setting('data_directory'),'server_version',current_setting('server_version'),
 'raw_capture_schema_exists',EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='raw_capture'),
 'relations',COALESCE((SELECT json_agg(row_to_json(r) ORDER BY schema_name,relname) FROM relations r),'[]'::json),
 'public_core_relation_bytes',COALESCE((SELECT sum(total_bytes) FROM relations WHERE schema_name='public'
 AND relname NOT IN ('ghost_twap_audit','polymarket_evidence_payloads','polymarket_market_observations','polymarket_quote_observations','binance_microstructure_1s')),0),
 'raw_capture_relation_bytes',COALESCE((SELECT sum(total_bytes) FROM relations WHERE schema_name='raw_capture'),0),
 'tablespaces',(SELECT json_agg(json_build_object('name',spcname,'location',pg_tablespace_location(oid))) FROM pg_tablespace)); COMMIT;"""
r={'read_only':True,'started_wall_ns':str(time.time_ns()),'host':'152.42.247.86','sql':sql}
r['database']=json.loads(command(['sudo','-u','postgres','psql','-X','-q','-A','-t','-v','ON_ERROR_STOP=1','-d','price_collector','-c',sql],15))
r['head']=command(['sudo','-u','pricecollector','git','-C',str(base),'rev-parse','HEAD'])
r['git_status']=command(['sudo','-u','pricecollector','git','-C',str(base),'status','--porcelain'])
units=['price-collector','price-collector-polymarket-chainlink','price-collector-binance-futures','price-collector-polymarket-probabilities','price-api','redis-server']
r['services']={u:dict(line.split('=',1) for line in command(['systemctl','show',u,'-p','ActiveState','-p','SubState','-p','MainPID'],5).splitlines()) for u in units}
keys={'GHOST_TWAP_ENABLED','GHOST_TWAP_CANARY_START_MS','GHOST_TWAP_STATE_DIRECTORY','GHOST_TWAP_DATABASE_FILESYSTEM_PATH','GHOST_TWAP_AUDIT_MAX_RECORDS','GHOST_TWAP_RECORD_MAX_BYTES','POLYMARKET_EVIDENCE_ENABLED','POLYMARKET_EVIDENCE_WARN_RELATION_MB','POLYMARKET_EVIDENCE_MAX_RELATION_MB','BINANCE_MICROSTRUCTURE_ENABLED','BINANCE_MICROSTRUCTURE_RETENTION_DAYS','BINANCE_MICROSTRUCTURE_WARN_RELATION_MB','BINANCE_MICROSTRUCTURE_MAX_RELATION_MB','RAW_FUTURES_TRACE_ENABLED','RAW_CHAINLINK_EVENTS_ENABLED','RAW_CAPTURE_RETENTION_HOURS','RAW_CAPTURE_MAX_RELATION_MB'}
r['configured_env_whitelist']={}
for name in ('collector.env','polymarket-chainlink.env','binance-futures.env','polymarket-probabilities.env'):
 path=pathlib.Path('/etc/price-collector')/name
 if not path.exists():continue
 values,duplicates={},[]
 for line in path.read_text().splitlines():
  if '=' not in line or line.lstrip().startswith('#'):continue
  key,value=line.split('=',1);key=key.strip()
  if key in keys:
   if key in values:duplicates.append(key)
   values[key]=value.strip().strip(chr(34)).strip(chr(39))
 r['configured_env_whitelist'][name]={'values':values,'duplicate_keys':duplicates}
r['running_process_env_whitelist']={}
for unit in units[:4]:
 values={};pid=int(r['services'][unit]['MainPID'])
 if pid:
  for part in pathlib.Path('/proc/'+str(pid)+'/environ').read_bytes().split(b'\0'):
   if b'=' not in part:continue
   key,value=part.split(b'=',1);key=key.decode(errors='replace')
   if key in keys:values[key]=value.decode(errors='replace')
 r['running_process_env_whitelist'][unit]=values
r['code_default_whitelist']={}
for name in ('config.py','polymarket_evidence.py'):
 for node in ast.walk(ast.parse((base/'price_collector'/name).read_text())):
  if isinstance(node,ast.AnnAssign) and isinstance(node.target,ast.Name) and node.target.id in keys:
   value=node.value
   if isinstance(value,ast.Call):value=next((k.value for k in value.keywords if k.arg=='default'),None)
   try:default=ast.literal_eval(value)
   except (ValueError,TypeError):continue
   r['code_default_whitelist'][node.target.id]={'value':default,'source':name}
def number(node):
 if isinstance(node,ast.Constant) and type(node.value) is int:return node.value
 if isinstance(node,ast.BinOp) and isinstance(node.op,(ast.Mult,ast.Pow)):
  a,b=number(node.left),number(node.right);return a*b if isinstance(node.op,ast.Mult) else a**b
 raise ValueError('unsupported constant')
r['ghost_fixed_code_caps']={}
for node in ast.parse((base/'price_collector'/'ghost_twap_runtime.py').read_text()).body:
 if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in {'WARN_BYTES','STOP_BYTES','BUDGET_BYTES','MAX_ROWS','RESERVE_BYTES','CANARY_MS'}:
  r['ghost_fixed_code_caps'][node.targets[0].id]=number(node.value)
paths={r['database']['data_directory']}|{t['location'] for t in r['database']['tablespaces'] if t['location']}
r['filesystems']=[]
for value in sorted(paths):
 path=pathlib.Path(value).resolve();s=os.statvfs(path)
 r['filesystems'].append({'path':str(path),'device_id':path.stat().st_dev,'total_bytes':s.f_blocks*s.f_frsize,'free_bytes':s.f_bfree*s.f_frsize,'available_bytes':s.f_bavail*s.f_frsize})
process=r['running_process_env_whitelist']['price-collector-polymarket-chainlink']
configured=r['configured_env_whitelist'].get('collector.env',{}).get('values',{})
r['ghost_producer_disabled_checks']={'running_process_false':process.get('GHOST_TWAP_ENABLED','false').lower()=='false','collector_env_false':configured.get('GHOST_TWAP_ENABLED','false').lower()=='false','redis_key_absent':command(['redis-cli','EXISTS','btc:live:ghost_chainlink_twap_60s'])=='0'}
r['experiment_limits']={'aggregate_relation_bytes':2*1024**3,'minimum_available_bytes':11*1024**3,'statement_timeout_seconds':20,'lock_timeout_seconds':1,'total_seconds':1200,'batch_rows':500}
r['initial_headroom_ok']=all(f['available_bytes']>=11*1024**3 for f in r['filesystems'])
r['all_services_active']=all(v['ActiveState']=='active' for v in r['services'].values())
r['metadata_only']=True
r['notes']=['Sizes are allocated heap/TOAST/index bytes, not row counts or payload bytes.','Database size includes catalog/free allocation and optional evidence; public_core_relation_bytes excludes the five named optional/ghost tables.','Live collectors continued; filesystem and service readings are subsequent point checks.','Only whitelisted environment values are emitted; missing overrides use source defaults, not zero capacity.','No rows read, written, deleted or vacuumed. An earlier metadata-only attempt stopped at the root git ownership check; this successful attempt runs git as pricecollector.']
r['completed_wall_ns']=str(time.time_ns())
print(json.dumps(r,sort_keys=True))
